'use strict';
let clipLoopSession=null,clipLoopRAF=0;
$('previewClipTransition').after(Object.assign(document.createElement('button'),{id:'loopClipTransition',textContent:'Loop preview'}));
$('clipTransitionLength').closest('label').after(Object.assign(document.createElement('label'),{innerHTML:'Transition intensity<input id="clipTransitionIntensity" type="range" min="0" max="100" value="100">'}));
$('clipEffectsDialog').querySelector('.tool-heading').after(Object.assign(document.createElement('details'),{id:'transitionLoopPanel',innerHTML:'<summary>Live transition preview</summary><canvas id="transitionLoopCanvas" width="640" height="360" aria-label="Looping transition preview"></canvas><input id="transitionLoopPosition" type="range" min="0" max="1" step="0.001" value="0.5" aria-label="Transition preview position"><p id="transitionLoopStatus" role="status" class="note">Preview the current settings without changing the project. Apply transition to save them.</p>'}));
function stopClipLoop(){cancelAnimationFrame(clipLoopRAF);if(clipLoopSession)clipLoopSession.closed=true;clipLoopSession=null;$('loopClipTransition').textContent='Loop preview';pauseVideoMedia();window.editorTaskBusy=false}
async function paintTransitionLoop(position=null){const session=clipLoopSession;if(!session||session.busy||project!==session.project||current()!==session.scene)return;const o=current().objects.find(o=>o.id===$('transitionFromClip').value),next=current().objects.find(o=>o.id===$('transitionToClip').value);if(!o||!next||!adjacentClips(o).some(a=>a.id===next.id))throw Error('Choose two adjacent image or video clips.');session.busy=true;try{const duration=clamp(+$('clipTransitionLength').value||.5,.1,Math.min(3,clipEnd(o)-clipStart(o))),raw=position??((performance.now()-session.started)/1000*previewSpeed()% (duration+.3))/duration,progress=clamp(raw,0,.9999),at=clipEnd(o)-duration+progress*duration;for(const [object,t]of[[o,at],[next,clipStart(next)]])if(object.type==='video'){const video=videoFor(object);video.pause();await seekVideo(video,(object.sourceOffset||0)+(t-clipStart(object))*videoSpeed(object))}if(session!==clipLoopSession||session.closed)return;const old=o.exitTransition;try{o.exitTransition={toId:next.id,type:chosenClipTransition,duration,intensity:+$('clipTransitionIntensity').value/100};const canvas=$('transitionLoopCanvas'),source=session.surface,ctx=source.getContext('2d');renderSceneFrame(ctx,current(),at);const g=canvas.getContext('2d'),view=projectView(),scale=Math.min(640/view.width,360/view.height),w=view.width*scale,h=view.height*scale;g.fillStyle='#101115';g.fillRect(0,0,640,360);g.drawImage(source,view.left,0,view.width,view.height,(640-w)/2,(360-h)/2,w,h)}finally{if(old===undefined)delete o.exitTransition;else o.exitTransition=old}$('transitionLoopPosition').value=progress;$('transitionLoopStatus').textContent=chosenClipTransition+' · '+duration.toFixed(2)+'s · '+$('clipTransitionIntensity').value+'% · draft preview'}finally{session.busy=false}}
async function startClipLoop(){if(clipLoopSession){if(clipLoopSession.paused){clipLoopSession.paused=false;clipLoopSession.started=performance.now()-+$('transitionLoopPosition').value*(+$('clipTransitionLength').value||.5)/previewSpeed()*1000;$('loopClipTransition').textContent='Stop loop';clipLoopRAF=requestAnimationFrame(clipLoopSession.tick);return}return stopClipLoop()}if(recording||audioBusy||speechProcessing)return;stop();const source=document.createElement('canvas');source.width=960;source.height=540;const session={project,scene:current(),started:performance.now(),surface:source,busy:false,closed:false,paused:false};clipLoopSession=session;window.editorTaskBusy=true;$('transitionLoopPanel').open=true;$('loopClipTransition').textContent='Stop loop';try{await preloadProductionAssets(current());if(session!==clipLoopSession)return;const tick=async()=>{if(clipLoopSession!==session)return;try{await paintTransitionLoop();if(session.paused&&session.scrubPosition!==undefined){const position=session.scrubPosition;delete session.scrubPosition;await paintTransitionLoop(position)}if(clipLoopSession===session&&!session.paused)clipLoopRAF=requestAnimationFrame(tick)}catch(e){stopClipLoop();$('transitionLoopStatus').textContent=e.message}};session.tick=tick;tick()}catch(e){stopClipLoop();$('transitionLoopStatus').textContent=e.message}}
$('loopClipTransition').onclick=startClipLoop;$('clipEffectsDialog').addEventListener('close',stopClipLoop);$('transitionLoopPosition').oninput=async e=>{const position=+e.target.value;if(!clipLoopSession)await startClipLoop();const session=clipLoopSession;if(!session)return;session.paused=true;cancelAnimationFrame(clipLoopRAF);$('loopClipTransition').textContent='Resume loop';if(session.busy){session.scrubPosition=position;return}try{await paintTransitionLoop(position)}catch(error){$('transitionLoopStatus').textContent=error.message}};
const closeBeforeClipLoop=$('closeClipEffects').onclick;$('closeClipEffects').onclick=()=>{stopClipLoop();return closeBeforeClipLoop()};$('clipEffectsDialog').addEventListener('cancel',stopClipLoop);

const transitionTargetsBeforeIntensity=renderTransitionTargets;renderTransitionTargets=function(){transitionTargetsBeforeIntensity();const o=current().objects.find(o=>o.id===$('transitionFromClip').value);$('clipTransitionIntensity').value=(o?.exitTransition?.intensity??1)*100};
